7	import { EXECUTOR_WORKFLOW, taskSecretNames, secretEnvLine, passesSecret } from '../converge-workflows.mjs';
8	
9	// A secret reaches a task only if the executor workflow names it STATICALLY — that
10	// is Actions' rule, and the reason the wiring converge stamps one env line per
11	// declared secret rather than one `toJSON(secrets)` (converge-workflows.mjs says why
12	// the cheap shape is not available). But `.github/workflows/` is the one directory a
13	// member's converge may not push to, so that file is scaffolded once at adoption and
14	// never regenerated: every task and every invocation endpoint added afterwards
15	// declares a secret the executor still does not carry.
16	//
17	// Nothing catches the drift. The declaration is valid, the queue picks the item up,
18	// the run starts, and only then does the worker read `process.env.<NAME>` as undefined,
19	// and code-work that reads its own secret may not say anything at all.
20	//
21	// THE LIST IS THE TASKS', and only theirs: the packs a repo declares, shared and local
22	// alike, have tasks, and what those tasks require is what the executor must carry (the
23	// owner's call). An invocation endpoint's `tokenSecret` is repo config rather than a
24	// task declaration, so it is not on this list — the converge stamps it all the same
25	// (`secretNames`), and the invocation call names it precisely when a job does not carry
26	// it (queue/invoke.mjs), which is the surface that case already had.
27	//
28	// ADVISORY, DELIBERATELY, for `conformance-workflow`'s reason: the remedy is a
29	// human-merged PR to `.github/workflows/`, the one fix a member's own machinery
30	// cannot make. Blocking would turn such a member red with no move of its own to
31	// clear it, every night, until a person happened to look.
32	//
33	// The expectation is COMPUTED BY THE SAME CODE the converge stamps with
34	// (`taskSecretNames`) over the same walk discovery makes (`taskDeclarationFiles`), so
35	// this cannot hold a second opinion of what the file should say. Extra names in the
36	// workflow are not a finding: a member that dropped a task keeps a harmless line, as
37	// does one whose executor carries an endpoint token.
38	const rule = {
39	  id: 'executor-workflow-secrets',
40	  severity: 'advisory',
41	  description: 'The executor workflow passes every secret the tasks of this repo\'s packs declare',
42	  doc: 'packs/claudinite-tasks/README.md',
43	  why: 'a secret the executor does not name statically never reaches the job, and the task fails only once the queue has already picked its item up',
44	
45	  run(ctx) {
46	    const expected = taskSecretNames(taskDeclarations(ctx));
47	    if (!expected.length) return [];
48	    const text = ctx.read(EXECUTOR_WORKFLOW);
49	    const missing = text === null ? expected : expected.filter((name) => !passesSecret(text, name));
50	    if (!missing.length) return [];
51	    return [finding(rule, {
52	      file: EXECUTOR_WORKFLOW,
53	      line: text === null ? null : markerLine(text),
54	      what: text === null
55	        ? `is missing, so nothing passes ${missing.join(', ')} to the executor`
56	        : `does not pass ${missing.join(', ')}, which the tasks of this repo's packs declare`,
57	      fix: `add ${missing.map((n) => `\`${secretEnvLine(n).trim()}\``).join(' and ')} to the executor's env, beneath its \`# claudinite:secrets\` marker — this pack's \`converge-workflows.mjs <owner/repo>\` (under \`.claudinite/shared/\` in a member) writes the whole list — and get that PR merged: a converge cannot push to .github/workflows/. Setting the repository secret itself is the other half`,
58	    })];
59	  },
60	};
61	
62	// Every ACTIVE pack's task declarations, parsed but not validated — this rule asks
63	// one field of them, and a declaration another check will reject still tells the
64	// truth about which secret it needs. `ctx.packs` is what the runner discovered.
65	function taskDeclarations(ctx) {
66	  const { found } = taskDeclarationFiles(ctx.root, (ctx.packs ?? []).filter((p) => isActive(p, ctx.config)));
67	  const out = [];
68	  for (const { file } of found) {
69	    // A retired `task.mjs` declaration is a module, and reading one needs the async
70	    // import this synchronous surface cannot make; the JSON form is what the
71	    // declarations-to-JSON migration leaves behind.
72	    if (!file.endsWith(TASK_DECLARATION_FILE)) continue;
73	    const text = ctx.read(relative(ctx.root, file).split(sep).join('/'));
74	    if (text === null) continue;
75	    try { out.push(normalizeTaskDeclaration(parseTaskDeclaration(text))); } catch { /* the declaration checks own a file that will not parse */ }
76	  }
77	  return out;
78	}
79	
80	const markerLine = (text) => {
81	  const at = text.search(/^[ \t]*# claudinite:secrets\b/m);
82	  return at < 0 ? null : text.slice(0, at).split('\n').length;
83	};
84	
85	export default rule;

